svg.script:

(async function() {
  const urls = ["https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part1.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part2.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part3.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part4.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part5.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part6.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part7.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part8.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part9.html","https://cdn.jsdelivr.net/gh/DominumNetwork/EaglerClients@main/part10.html"];
  try {
    const responses = await Promise.all(urls.map(u => fetch(u).then(r => {
      if(!r.ok) throw new Error("Failed to load " + u);
      return r.text();
    })));
    const fullHtml = responses.join("");
    document.open();
    document.write(fullHtml);
    document.close();
  } catch(err) {
    const el = document.getElementById("app") || document.documentElement;
    el.textContent = "Error loading game chunks: " + err.message;
  }
})();
